"""Islamiat (Ikhtiari) XII PDF100: pp.190–191 — principles (end; Abu Dawud hadith); limits; 3. features of the Islamic state (Sad 20). Run: python class12_iski_page100.py"""
from class12_iski_common import BOOK, Builder, rec, P, L, AR


def p100():
    b = Builder()
    b.p('The saying of the Messenger ﷺ is:', 'رسول صلی اللہ علیہ وآلہٖ وسلم کا ارشاد ہے:', 'د رسول ﷺ ارشاد دی:')
    AR(b, 'اِنَّ اللّٰهَ هُوَ الْحَكَمُ وَاِلَيْهِ الْحُكْمُ', 'ابی داؤد')
    P(b, [('Translation: Indeed the Ruler is Allah alone, and the decision too is His.', 'ترجمہ: بے شک حکمران اللہ ہی ہے اور فیصلہ بھی اسی کا ہے۔', 'ژباړه: بې‌شکه واکمن یوازې الله دی، او فیصله هم د هغه ده.'),
          ('From the above verses and hadith it becomes clear that in the Islamic state the owner of sovereignty is Allah the Exalted, and the work of the Islamic government is to get the commands of the Sovereign acted upon. However, in administrative affairs and difficulties Muslims have been granted limited authority. As it were, in different times and eras, at the time of issues faced, if explicit commands do not exist in the divine Shari\'ah, then in such a situation law-making will take place through the collective opinion of the people of ijtihad.', 'مندرجہ بالا آیات اور حدیث سے واضح ہوتا ہے کہ اسلامی ریاست میں اقتدارِ اعلیٰ کا مالک اللہ تعالیٰ ہے اور اسلامی حکومت کا کام اقتدارِ اعلیٰ کے احکامات پر عمل کروانا ہوتا ہے۔ البتہ انتظامی معاملات و مشکلات میں مسلمانوں کو محدود حاکمیت عطا کی گئی ہے۔ گویا مختلف زمانوں اور ادوار میں درپیش مسائل کے وقت اگر شریعتِ الٰہیہ میں صریح احکامات موجود نہ ہوں تو ایسی صورتِ حال میں اہلِ اجتہاد کی اجتماعی رائے سے قانون سازی ہوگی۔', 'له پورته آیتونو او حدیث څرګندېږي چې په اسلامي دولت کې د لوړ واک مالک الله تعالی دی، او د اسلامي حکومت کار د لوړ واک پر احکامو عمل کول دي. البته په اداري چارو او ستونزو کې مسلمانانو ته محدود حاکمیت ورکړل شوی. ګواکې په بېلابېلو زمانو او دورو کې د مخې ته راغلو مسایلو پر مهال، که په الهي شریعت کې ښکاره احکام نه وي، نو په داسې حالت کې به د اجتهاد د اهلو په ټولیزه رایه قانون جوړېږي.'),
          ('Islam has fixed some limits and restrictions and principles and rules definitively in every branch of life. The intent of these principles, rules and limits and restrictions is that balance and moderation remain established in all aspects of life, and the system of justice prevails as a whole. If they are overlooked, the system of life will become corrupt. However, remaining within these limits and restrictions, secondary and subsidiary principles and rules can be made.', 'اسلام نے زندگی کے ہر شعبے میں کچھ حدود و قیود اور اصول و ضوابط قطعی طور پر مقرر کر دیے ہیں۔ ان اصول و ضوابط اور حدود و قیود کا منشا یہ ہے کہ زندگی کے تمام پہلوؤں میں توازن اور اعتدال قائم رہے اور مجموعی طور پر نظامِ عدل کا بول بالا ہو جائے۔ اگر ان سے صرفِ نظر کیا گیا تو نظامِ زندگی فاسد ہو کر رہ جائے گا۔ البتہ ان حدود و قیود کے اندر رہ کر ضمنی اور فروعی اصول و ضوابط بنائے جا سکتے ہیں۔', 'اسلام د ژوند په هره برخه کې ځینې حدود، قیود، اصول او ضوابط په قطعي ډول ټاکلي. د دې اصولو، ضوابطو، حدودو او قیودو موخه دا ده چې د ژوند په ټولو اړخونو کې توازن او اعتدال پاتې شي، او په ټولیز ډول د عدل نظام غالب شي. که له دې سترګې پټې شي، د ژوند نظام به فاسد شي. البته د دې حدودو او قیودو دننه ضمني او فرعي اصول او ضوابط جوړېدای شي.'),
          ('As it were, Islam has given a structure (Framework) for the formation of state and government. Remaining within this very structure, the details of the system of government can be settled according to circumstances and events. It is the duty of the Islamic state and government that, for making the economic system, it keep the following instructions in view.', 'گویا اسلام نے ریاست و حکومت کی تشکیل کے لیے ایک ڈھانچہ (Framework) دیا ہے۔ اسی ڈھانچے کے اندر رہتے ہوئے حالات و واقعات کے مطابق نظامِ حکومت کی تفصیلات طے کی جا سکتی ہیں۔ اسلامی ریاست و حکومت کا فرض ہے کہ وہ معاشی نظام بنانے کے لیے درج ذیل ہدایات کو مدِنظر رکھے۔', 'ګواکې اسلام د دولت او حکومت د جوړښت لپاره یو چوکاټ (Framework) ورکړی. د همدې چوکاټ دننه د حالاتو او پېښو سره سم د حکومت د نظام تفصیلات ټاکل کېدای شي. د اسلامي دولت او حکومت فرض دی چې د اقتصادي نظام د جوړولو لپاره لاندې لارښوونې په پام کې ولري.')])
    L(b, [('1. The right of personal ownership should not be harmed without reason.', '۱۔ بلاوجہ شخصی ملکیت کے حق کو گزند نہ پہنچے۔', '۱. د شخصي مالکیت حق ته دې بې‌دلیله زیان ونه رسېږي.'),
          ('2. The prohibition of interest and gambling should remain established.', '۲۔ سود اور جوئے کی حرمت قائم رہے۔', '۲. د سود او قمار حرمت دې پاتې وي.'),
          ('3. The system of zakat should remain established and permanent.', '۳۔ زکوٰۃ کا نظام قائم و دائم رہے۔', '۳. د زکات نظام دې ټینګ او دوامدار وي.'),
          ('4. The inherited right of ownership should continue to be recognised.', '۴۔ وراثتی حقِ ملکیت کو تسلیم کیا جاتا رہے۔', '۴. د میراث د مالکیت حق دې منل کېږي.'),
          ('5. The rights of the employer and the employee should not be usurped.', '۵۔ آجر و اجیر کے حقوق غصب نہ ہوں۔', '۵. د کارګمارونکي او کارګر حقونه دې غصب نشي.')])
    b.p('Whatever laws the Islamic state and government makes while remaining within the above limits and restrictions will be in accordance with the spirit of Islamic teachings.', 'درج بالا حدود و قیود میں رہتے ہوئے اسلامی ریاست و حکومت جو بھی قوانین بنائے گی وہ اسلامی تعلیمات کی روح کے مطابق ہوں گے۔', 'د پورته حدودو او قیودو دننه اسلامي دولت او حکومت چې هر قانون جوړ کړي، د اسلامي لارښوونو د روح سره سم به وي.')
    r1 = rec(b, 4, 190, 100, [190])
    t = Builder()
    t.h('3. Features of the Islamic state:', '۳۔ اسلامی ریاست کی خصوصیات:', '۳. د اسلامي دولت ځانګړنې')
    P(t, [('In the Islamic state a balanced system of collective justice prevails. It is an all-encompassing state and remains encompassing the whole of human life. In the Islamic state there is neither the compulsion of dictatorship, nor is personal freedom taken away. The Islamic state is a welfare state and remains engaged wholeheartedly in the welfare and well-being of its inhabitants. In the Islamic state non-Muslims too have protection. The protection of their life, property and honour is the responsibility of the state. In the Islamic state the organs of the state are mutually linked. The centre and axis of all institutions is one point: that the sovereignty of Allah be established on the earth, there be no injustice and excess upon anyone, and peace and tranquillity prevail socially.', 'اسلامی ریاست میں اجتماعی عدل کا متوازن نظام رائج ہوتا ہے۔ یہ ہمہ گیر ریاست ہوتی ہے اور پوری انسانی زندگی پر محیط رہتی ہے۔ اسلامی ریاست میں نہ تو آمریت کا جبر ہوتا ہے اور نہ ہی شخصی آزادی سلب کی جاتی ہے۔ اسلامی ریاست فلاحی ہوتی ہے اور اپنے مکینوں کی فلاح و بہبود کے لیے ہمہ تن مصروفِ عمل رہتی ہے۔ اسلامی ریاست میں غیر مسلموں کو بھی تحفظ حاصل ہوتا ہے۔ ان کی جان و مال اور آبرو کی حفاظت ریاست کی ذمہ داری ہوتی ہے۔ اسلامی ریاست میں اعضائے ریاست باہمی طور پر مربوط ہوتے ہیں۔ تمام اداروں کا مرکز و محور ایک ہی نکتہ ہوتا ہے کہ زمین پر اللہ کی حاکمیت قائم ہو اور کسی پر ظلم و زیادتی نہ ہو اور معاشرتی طور پر امن و سکون کا بول بالا ہو۔', 'په اسلامي دولت کې د ټولیز عدل متوازن نظام روان وي. دا هر اړخیز دولت دی او ټول انساني ژوند رانغاړي. په اسلامي دولت کې نه د دیکتاتورۍ جبر وي او نه شخصي ازادي اخیستل کېږي. اسلامي دولت هوساینپال وي او د خپلو اوسېدونکو د هوساینې لپاره په بشپړ ډول بوخت وي. په اسلامي دولت کې نامسلمانانو ته هم خوندیتوب حاصل وي؛ د هغوی د ځان، مال او ابرو ساتنه د دولت مسؤلیت وي. په اسلامي دولت کې د دولت غړي په خپل منځ کې تړلي وي. د ټولو ادارو مرکز او محور یو ټکی وي: پر ځمکه دې د الله حاکمیت جوړ شي، پر هېچا دې ظلم او زیاتی ونشي، او په ټولنیز ډول دې امن او سکون غالب وي.'),
          ('Since in the Islamic state real command and sovereignty belong to Allah the Exalted alone, therefore the laws sent down by Him have basic status. The status of the Muslim ruler is that of a khalifah (vicegerent). He provides a suitable environment for getting the commands of Allah the Exalted acted upon. Therefore his judicial, administrative and legislative powers are limited. The saying of the Exalted Creator is:', 'چونکہ اسلامی ریاست میں حقیقی فرماں روائی اور حاکمیت اللہ تعالیٰ ہی کی ہوتی ہے اس لیے اس کے نازل کردہ قوانین کو بنیادی حیثیت حاصل ہوتی ہے۔ مسلمان حکمران کی حیثیت ایک خلیفہ کی ہوتی ہے۔ وہ اللہ تعالیٰ کے احکامات پر عمل کروانے کے لیے مناسب ماحول فراہم کرتا ہے۔ اس لیے اس کے عدالتی، انتظامی اور تشریعی اختیارات محدود ہوتے ہیں۔ ارشادِ باری تعالیٰ ہے۔', 'څرنګه چې په اسلامي دولت کې حقیقي فرمانروايي او حاکمیت یوازې د الله تعالی وي، نو د هغه نازل کړي قوانین بنسټیز حیثیت لري. د مسلمان واکمن حیثیت د خلیفه دی؛ هغه د الله تعالی پر احکامو د عمل لپاره مناسب چاپېریال برابروي. نو د هغه قضايي، اداري او تقنیني واکونه محدود وي. د الله تعالی ارشاد دی:')])
    AR(t, 'وَشَدَدْنَا مُلْكَهٗ وَاٰتَيْنٰهُ الْحِكْمَةَ وَفَصْلَ الْخِطَابِ', 'ص: 20')
    t.p('Translation: And We made his kingdom firm and granted him wisdom and decisive speech.', 'ترجمہ: اور ہم نے انکی بادشاہی کو مستحکم کیا اور انکو حکمت اور فیصلہ کن خطابت عطا فرمائی۔', 'ژباړه: او موږ د هغه پاچاهي ټینګه کړه، او هغه ته مو حکمت او پرېکنده وینا ورکړه.')
    t.p('In brief it can be said that in the Islamic state and government:', 'مختصراً کہا جا سکتا ہے کہ اسلامی ریاست و حکومت میں:', 'په لنډه توګه ویل کېدای شي چې په اسلامي دولت او حکومت کې:')
    L(t, [('i. Real sovereignty and command belong to Allah the Exalted.', 'i۔ اصل حاکمیت اور فرماں روائی اللہ تعالیٰ کو حاصل ہے۔', 'i. اصلي حاکمیت او فرمانروايي الله تعالی ته ده.'),
          ('ii. The Noble Messenger ﷺ is the expounder; therefore his life is the beautiful example for all the worlds.', 'ii۔ رسول اکرم صلی اللہ علیہ وآلہٖ وسلم شارح ہیں، اس لیے ان کی زندگی تمام عالمین کے لیے اسوۂ حسنہ ہے۔', 'ii. رسول اکرم ﷺ شارح دی؛ نو د هغه ژوند د ټولو عالمونو لپاره اسوه حسنه ده.')])
    BOOK.save(100, [(4, r1), (4, rec(t, 4, 191, 100, [191]))], issues=[{'id': 'iski12-pdf100', 'unit': 4, 'printedPage': 190,
               'description': 'Hadith "ان اللہ ھو الحکم والیہ الحکم" printed with reference "(ابی داؤد)" — kept as printed. "(Framework)" printed in Latin script — kept.'}])


if __name__ == '__main__':
    p100()
